{
  "command": "cat scripts/plot_prior_kl.py; git log --oneline -5 -- scripts/plot_prior_kl.py; grep -rn \"plot_prior_kl\\|prior_kl\" --include=*.md --include=*.html --include=*.py --include=*.ipynb . 2>/dev/null | grep -v \"^./scripts/plot_prior_kl.py\" | head -20",
