  "command": "grep -rln \"plot_prior_kl\\|kl-M1_210210\" wiki scripts notebooks 2>/dev/null; ls wiki/analyses/m1-210210-reference/ | grep -i kl; ls results/dr2-quiescent-new-defaults/210210-M1_210210 results/m1-210210-reference/tau-1/poly10/210210-M1_210210 2>&1 | head; ls ceridwen/.venv/bin/python",
