  "command": "grep -n \"plot_prior_kl\\|kl-M1_210210\\|barh\\|bar chart\" wiki/notes/m1-210210-reference.md wiki/notes/notebook-map.md wiki/notes/no-emission-mask.md wiki/research/experiments/e-m1-210210-reference.md wiki/research/experiments/e-dust-bump.md wiki/research/experiments/e-no-emission-mask.md; grep -n \"plot_prior_kl\\|barh\" notebooks/ceridwen_integrated_photometry_spectra.ipynb | head",
